"use client";

import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import { LayoutDashboard, Ticket } from "lucide-react";

const nav = [
  { name: "Dashboard", href: "/dashboard", icon: LayoutDashboard },
  { name: "IT Tickets", href: "/tickets", icon: Ticket },
  { name: "Admin Tickets", href: "/admin", icon: Ticket },
];

export function Sidebar({
  signOutAction,
  collapsed = false,
  logoLightSrc,
  logoDarkSrc,
  logoCollapsedSrc,
  logoAlt = "Logo",
}: {
  signOutAction?: (formData: FormData) => void | Promise<void>;
  collapsed?: boolean;
  logoLightSrc?: string;
  logoDarkSrc?: string;
  logoCollapsedSrc?: string;
  logoAlt?: string;
}) {
  const pathname = usePathname();

  return (
    <aside
      className={`h-screen sticky top-0 border-r border-border bg-card ${
        collapsed ? "w-21" : "w-64"
      } transition-[width] duration-300 flex flex-col`}
    >
      <div className={`flex h-16 items-center justify-center px-4`}>
        <Link href="/dashboard" className={`flex items-center gap-2 justify-center`}>
          {collapsed ? (
            logoCollapsedSrc ? (
              <Image
                src={logoCollapsedSrc}
                alt={logoAlt}
                width={32}
                height={32}
                sizes="32px"
                quality={100}
                priority
              />
            ) : (
              <span className="inline-flex h-8 w-8 items-center justify-center rounded-md bg-icon-bg text-icon-fg font-semibold">HC</span>
            )
          ) : (logoLightSrc || logoDarkSrc) ? (
            <div className="relative h-8 w-35">
              {logoLightSrc && (
                <Image
                  src={logoLightSrc}
                  alt={logoAlt}
                  fill
                  sizes="140px"
                  quality={100}
                  className="object-contain block dark:hidden"
                  priority
                />
              )}
              {logoDarkSrc && (
                <Image
                  src={logoDarkSrc}
                  alt={logoAlt}
                  fill
                  sizes="140px"
                  quality={100}
                  className="object-contain hidden dark:block"
                  priority
                />
              )}
            </div>
          ) : (
            <>
              <span className="inline-flex h-8 w-8 items-center justify-center rounded-md bg-icon-bg text-icon-fg font-semibold">HC</span>
              <span className="font-semibold">Handy Comms</span>
            </>
          )}
        </Link>
      </div>

      <nav className="px-2 py-2 mt-2 space-y-2">
        {nav.map((item) => {
          const Icon = item.icon;
          const active = pathname?.startsWith(item.href);
          return (
            <Link
              key={item.href}
              href={item.href}
              aria-label={item.name}
              className={`group relative flex w-full items-center gap-3 rounded-lg py-2 text-sm transition-colors hover:bg-card2 ${collapsed ? "justify-center px-0" : "px-3"} ${active ? "bg-card2" : ""}`}
            >
              <Icon className="h-5 w-5 text-accent" />
              {!collapsed && <span className="text-text">{item.name}</span>}
              {collapsed && (
                <span
                  role="tooltip"
                  className="pointer-events-none absolute left-full top-1/2 z-10 -translate-y-1/2 translate-x-2 opacity-0 whitespace-nowrap rounded-md border border-border bg-card px-2 py-1 text-xs text-text shadow transition-all duration-150 group-hover:opacity-100 group-hover:translate-x-3 ml-3"
                >
                  {item.name}
                  <span className="absolute left-0 top-1/2 -translate-y-1/2 -ml-1.5 h-3 w-3 rotate-45 bg-card border-l border-t border-border" />
                </span>
              )}
            </Link>
          );
        })}
      </nav>

      {/* Bottom items (empty for now) */}
      <div className="mt-auto px-2 pb-3" />
    </aside>
  );
}
